337	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
338	// 只有本地数据保存成功才算关闭完成：写盘失败时内存变更随快照一并回滚，
339	// 返回错误与零值事项，不把尚未保存的关闭状态当作关闭结果。
340	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
341		itemID = clean(itemID)
342		operator = clean(operator)
343		if err := requireNonEmpty("操作人", operator); err != nil {
344			return Item{}, err
345		}
346	
347		var closed Item
348		err := svc.store.mutate(func(d *Data) error {
349			it, _ := findItem(d, itemID)
350			if it == nil {
351				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
352			}
353			if it.Closed {
354				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
355			}
356			sh, _ := findShift(d, it.CurrentShiftID)
357			if sh == nil || sh.Closed {
358				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
359					ErrShiftClosed, itemID, it.CurrentShiftID)
360			}
361			now := svc.now()
362			it.Closed = true
363			it.ClosedAt = &now
364			it.CloseOperator = operator
365			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
366			closed = *it
367			return nil
368		})
369		if err != nil {
370			// 保存失败时内存已回滚，不能把尚未保存的关闭状态当作关闭结果返回。
371			return Item{}, err
372		}
373		return closed, nil
374	}
