package handover

import (
	"testing"
	"time"
)

// 临时验证：报告是查询当时的独立深拷贝，两个方向都不串数据。
func TestShiftReportIsolationTmp(t *testing.T) {
	store, err := Open(t.TempDir() + "/d.json")
	if err != nil {
		t.Fatal(err)
	}
	svc := NewService(store)
	base := time.Date(2026, 1, 1, 8, 0, 0, 0, time.UTC)
	a, _ := svc.CreateShift("岗", "甲", base, base.Add(8*time.Hour), "")
	b, _ := svc.CreateShift("岗", "乙", base.Add(8*time.Hour), base.Add(16*time.Hour), "")
	it, _ := svc.AddItem(a.ID, "事项一", SeverityImportant, "", "丙")
	svc.CloseShift(a.ID)
	h, _ := svc.CreateHandover(a.ID, b.ID)
	svc.ProcessEntry(h.ID, it.ID, ActionReturn, "乙", "信息不全", "", "")

	rep1, err := svc.ShiftReport(a.ID)
	if err != nil {
		t.Fatal(err)
	}
	rep2, _ := svc.ShiftReport(a.ID)

	// 调用方改动 rep1 的每一个角落。
	*rep1.Shift.ClosedAt = base
	rep1.Shift.CloseRecord.Items[0].Content = "篡改"
	*rep1.Shift.CloseRecord.Items[0].ClosedAt = base
	rep1.CloseItems[0].Content = "篡改"
	li := rep1.LatestItems[it.ID]
	li.Content = "篡改"
	li.Events[0].Detail = "篡改"
	li.ShiftIDs[0] = "S999"
	rep1.LatestItems[it.ID] = li
	rep1.Outgoing.Entries[0].Content = "篡改"
	rep1.Outgoing.Entries[0].Rounds[0].Reason = "篡改"
	*rep1.Outgoing.Entries[0].ProcessedAt = base
	*rep1.Outgoing.CompletedAt = base
	rep1.Results[it.ID][0].Entry.Rounds[0].Reason = "篡改"
	rep1.Items = append(rep1.Items, Item{ID: "I999"})

	// rep2 不受影响。
	if rep2.Shift.CloseRecord.Items[0].Content != "事项一" {
		t.Fatal("rep2 被 rep1 的改动污染")
	}
	if rep2.Outgoing.Entries[0].Rounds[0].Reason != "信息不全" {
		t.Fatal("rep2 交接被污染")
	}
	// 系统数据不受影响：重新查询仍是原内容。
	rep3, _ := svc.ShiftReport(a.ID)
	if rep3.Shift.CloseRecord.Items[0].Content != "事项一" ||
		rep3.Outgoing.Entries[0].Rounds[0].Reason != "信息不全" ||
		rep3.LatestItems[it.ID].Content != "事项一" {
		t.Fatal("存储数据被报告改动污染")
	}
	// 成功保存其他业务操作后，本地改动不混入数据文件。
	if _, err := svc.ResubmitReturned(h.ID, it.ID, "甲", "已补充"); err != nil {
		t.Fatal(err)
	}
	store2, _ := Open(store.Path())
	rep4, _ := NewService(store2).ShiftReport(a.ID)
	if rep4.Shift.CloseRecord.Items[0].Content != "事项一" {
		t.Fatal("本地改动混入了数据文件")
	}
	// 系统处理不改写已取得的报告：rep2 仍是退回，rep3 也是退回；重新查询才是待处理。
	if rep2.Outgoing.Entries[0].Status != EntryReturned || rep3.Outgoing.Entries[0].Status != EntryReturned {
		t.Fatal("已取得的报告被后续处理改写")
	}
	if rep4.Outgoing.Entries[0].Status != EntryPending {
		t.Fatal("重新查询应显示重新提交后的待处理")
	}
}

